// C++17
#include <iostream>
#include <optional>

std::optional<double> mid(double bid, double ask) {
    if (bid > 0 && ask > 0) return (bid + ask) / 2;
    return std::nullopt;
}

int main() {
    std::cout << mid(99.5, 100.5).value() << "\n";         // 100
    std::cout << mid(-1.0, 100.5).value_or(99.9) << "\n";  // 99.9: last-trade fallback
}

// C++17
#include <iostream>
#include <type_traits>
#include <utility>
#include <variant>

struct Price   { double value; };
struct Missing { const char* why; };
using Quote = std::variant<Price, Missing>;    // Price OR Missing

void report(const Quote& q) {
    std::visit([](const auto& alt) {
        using T = std::decay_t<decltype(alt)>;      // decltype - next lesson
        if constexpr (std::is_same_v<T, Price>)     // if constexpr - last lesson
            std::cout << "px " << alt.value << "\n";
        else
            std::cout << "miss " << alt.why << "\n";
    }, q);
}

int main() {
    report(Quote{Price{100.25}});
    report(Quote{Missing{"halt"}});
}

